1	export type Cell = [x: number, y: number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isNeighbourOf(cell: Cell, candidate: Cell): boolean {
8	  const [x, y] = cell;
9	  const [candidateX, candidateY] = candidate;
10	  const isWithinOneStep =
11	    Math.abs(candidateX - x) <= 1 && Math.abs(candidateY - y) <= 1;
12	  return isWithinOneStep && !isSameCell(cell, candidate);
13	}
14	
15	function countNeighbours(liveCells: Cell[], cell: Cell): number {
16	  return liveCells.filter((candidate) => isNeighbourOf(cell, candidate)).length;
17	}
18	
19	function survives(cell: Cell, liveCells: Cell[]): boolean {
20	  const neighbours = countNeighbours(liveCells, cell);
21	  return neighbours === 2 || neighbours === 3;
22	}
23	
24	function neighboursOf([x, y]: Cell): Cell[] {
25	  const offsets = [-1, 0, 1];
26	  return offsets.flatMap((dx) =>
27	    offsets
28	      .filter((dy) => !(dx === 0 && dy === 0))
29	      .map((dy): Cell => [x + dx, y + dy]),
30	  );
31	}
32	
33	function isBorn(cell: Cell, liveCells: Cell[]): boolean {
34	  return (
35	    !liveCells.some((live) => isSameCell(live, cell)) &&
36	    countNeighbours(liveCells, cell) === 3
37	  );
38	}
39	
40	function distinctCells(cells: Cell[]): Cell[] {
41	  return cells.filter(
42	    (cell, index) =>
43	      cells.findIndex((other) => isSameCell(other, cell)) === index,
44	  );
45	}
46	
47	export function nextGeneration(liveCells: Cell[]): Cell[] {
48	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
49	  const births = distinctCells(
50	    liveCells.flatMap(neighboursOf).filter((cell) => isBorn(cell, liveCells)),
51	  );
52	  return [...survivors, ...births];
53	}
